#!/usr/bin/env python3

from pathlib import Path
import struct
import zlib


MAGIC = b"SEAL"


def unpack_bits(bits: list[int]) -> bytes:
    output = bytearray()
    for offset in range(0, len(bits) - 7, 8):
        value = 0
        for bit in bits[offset:offset + 8]:
            value = (value << 1) | bit
        output.append(value)
    return bytes(output)


def extract_pages(data: bytes) -> list[tuple[int, list[int]]]:
    if data[:2] != bytes([247, 2]):
        raise ValueError("not a version-2 DVI file")
    position = 14
    comment_length = data[position]
    position += 1 + comment_length
    pages = []

    while position < len(data):
        opcode = data[position]
        position += 1
        if opcode == 248:
            break
        if opcode == 138:
            continue
        if opcode != 139:
            raise ValueError(f"unexpected top-level opcode {opcode}")

        counters = struct.unpack(">10i", data[position:position + 40])
        position += 44  # ten counters plus previous-page pointer
        bits = []

        while True:
            opcode = data[position]
            position += 1
            if opcode == 140:
                break
            if opcode <= 127 or opcode in (138, 141, 142, 147, 152, 161, 166):
                continue
            if 128 <= opcode <= 131 or 133 <= opcode <= 136:
                position += (opcode - 127) if opcode <= 131 else (opcode - 132)
            elif opcode in (132, 137):
                position += 8
            elif 143 <= opcode <= 146:
                position += opcode - 142
            elif 148 <= opcode <= 151:
                bits.append(0)
                position += opcode - 147
            elif 153 <= opcode <= 156:
                bits.append(1)
                position += opcode - 152
            elif 157 <= opcode <= 160:
                position += opcode - 156
            elif 162 <= opcode <= 165:
                position += opcode - 161
            elif 167 <= opcode <= 170:
                position += opcode - 166
            elif 171 <= opcode <= 234:
                pass
            elif 235 <= opcode <= 238:
                position += opcode - 234
            elif 239 <= opcode <= 242:
                size = opcode - 238
                length = int.from_bytes(data[position:position + size], "big")
                position += size + length
            else:
                raise ValueError(f"unsupported page opcode {opcode}")

        pages.append((counters[0], bits))

    return pages


def solve(path: Path) -> bytes:
    pages = sorted(extract_pages(path.read_bytes()), key=lambda item: item[0])
    if [number for number, _ in pages] != list(range(len(pages))):
        raise ValueError("logical page counters are incomplete")
    packed = unpack_bits([bit for _, page_bits in pages for bit in page_bits])
    if not packed.startswith(MAGIC):
        raise ValueError("bad payload marker")
    length = struct.unpack(">H", packed[4:6])[0]
    flag = packed[6:6 + length]
    stored_crc = struct.unpack(">I", packed[6 + length:10 + length])[0]
    if zlib.crc32(flag) & 0xFFFFFFFF != stored_crc:
        raise ValueError("payload CRC mismatch")
    return flag


if __name__ == "__main__":
    print(solve(Path(__file__).with_name("final")).decode("ascii"))

#!/usr/bin/env python3

import argparse
from collections import Counter
from fractions import Fraction
import math
import os
from pathlib import Path
import re
import socket
import subprocess
import sys


FLAG_LENGTH = 98
KNOWN = "Securi"
PROMPT = b"> "


class Node:
    def __init__(self, freq, symbol, left=None, right=None):
        self.freq = freq
        self.symbol = symbol
        self.left = left
        self.right = right

    def __lt__(self, other):
        if self.freq == other.freq:
            return self.symbol < other.symbol
        return self.freq < other.freq


class Channel:
    def __init__(self, host=None, port=None):
        self.buffer = bytearray()
        self.process = None
        self.socket = None

        if host is None:
            root = Path(__file__).resolve().parent
            self.process = subprocess.Popen(
                [sys.executable, "-u", "chall.py"],
                cwd=root,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
            )
            self.read_fd = self.process.stdout.fileno()
            self.write_fd = self.process.stdin.fileno()
        else:
            self.socket = socket.create_connection((host, port), timeout=30)
            self.socket.settimeout(30)

    def send(self, data):
        if self.socket is not None:
            self.socket.sendall(data)
            return

        view = memoryview(data)
        while view:
            written = os.write(self.write_fd, view)
            view = view[written:]

    def recv(self):
        if self.socket is not None:
            data = self.socket.recv(65536)
        else:
            data = os.read(self.read_fd, 65536)
        if not data:
            raise EOFError("service closed the connection")
        return data

    def read_until(self, marker):
        while True:
            position = self.buffer.find(marker)
            if position != -1:
                end = position + len(marker)
                result = bytes(self.buffer[:end])
                del self.buffer[:end]
                return result
            self.buffer.extend(self.recv())

    def read_prompts(self, count):
        found = 0
        search_from = 0
        while found < count:
            position = self.buffer.find(PROMPT, search_from)
            if position == -1:
                search_from = max(0, len(self.buffer) - len(PROMPT) + 1)
                self.buffer.extend(self.recv())
                continue
            found += 1
            search_from = position + len(PROMPT)

        result = bytes(self.buffer[:search_from])
        del self.buffer[:search_from]
        return result

    def close(self):
        try:
            self.send(b"3\n")
        except (BrokenPipeError, EOFError, OSError):
            pass
        if self.socket is not None:
            self.socket.close()
        elif self.process is not None:
            try:
                self.process.wait(timeout=2)
            except subprocess.TimeoutExpired:
                self.process.terminate()


def recover_frequencies(observations, total_length):
    values = sorted(observations)
    samples = sum(observations.values())
    count = len(values)
    negative_infinity = float("-inf")

    scores = [negative_infinity] * (total_length + 1)
    scores[0] = 0.0
    parents = []

    for index, value in enumerate(values):
        next_scores = [negative_infinity] * (total_length + 1)
        next_parents = [None] * (total_length + 1)
        remaining_symbols = count - index - 1
        observed = observations[value]

        for used, previous in enumerate(scores):
            if previous == negative_infinity:
                continue
            maximum = total_length - used - remaining_symbols
            for frequency in range(1, maximum + 1):
                target = used + frequency
                score = previous + observed * math.log(frequency)
                if score > next_scores[target]:
                    next_scores[target] = score
                    next_parents[target] = (used, frequency)

        scores = next_scores
        parents.append(next_parents)

    if scores[total_length] == negative_infinity:
        raise ValueError("could not fit the observed values to the known length")

    result = {}
    used = total_length
    for index in range(count - 1, -1, -1):
        previous, frequency = parents[index][used]
        result[values[index]] = frequency
        used = previous

    if used != 0 or sum(result.values()) != total_length:
        raise AssertionError("frequency recovery failed")
    if samples == 0:
        raise ValueError("no observations")
    return result


def build_tree(frequencies):
    import heapq

    heap = [Node(frequency, symbol) for symbol, frequency in frequencies.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        left = heapq.heappop(heap)
        right = heapq.heappop(heap)
        heapq.heappush(
            heap,
            Node(
                left.freq + right.freq,
                min(left.symbol, right.symbol),
                left,
                right,
            ),
        )
    return heap[0]


def decode(bits, root):
    result = []
    node = root
    for bit in bits:
        node = node.left if bit == "0" else node.right
        if node.left is None and node.right is None:
            result.append(node.symbol)
            node = root
    if node is not root:
        raise ValueError("trailing partial symbol")
    return "".join(result)


def make_codes(node, prefix="", result=None):
    if result is None:
        result = {}
    if node.left is None and node.right is None:
        result[node.symbol] = prefix
    else:
        make_codes(node.left, prefix + "0", result)
        make_codes(node.right, prefix + "1", result)
    return result


def solve_linear_system(matrix, vector):
    size = len(vector)
    rows = [
        [Fraction(value) for value in matrix[index]] + [Fraction(vector[index])]
        for index in range(size)
    ]

    for column in range(size):
        pivot = next(
            (row for row in range(column, size) if rows[row][column] != 0),
            None,
        )
        if pivot is None:
            raise ValueError("singular system")
        rows[column], rows[pivot] = rows[pivot], rows[column]

        scale = rows[column][column]
        rows[column] = [value / scale for value in rows[column]]

        for row in range(size):
            if row == column:
                continue
            scale = rows[row][column]
            if scale == 0:
                continue
            rows[row] = [
                current - scale * source
                for current, source in zip(rows[row], rows[column])
            ]

    return [rows[index][-1] for index in range(size)]


def evaluate_polynomial(coefficients, value):
    result = Fraction(0)
    for coefficient in coefficients:
        result = result * value + coefficient
    return result


def collect(channel, samples, batch_size):
    channel.read_until(PROMPT)
    channel.send(b"1\n")
    response = channel.read_until(PROMPT)
    match = re.search(rb"([01]{32,})", response)
    if match is None:
        raise ValueError("could not find the long binary string")
    bits = match.group(1).decode("ascii")

    observations = Counter()
    completed = 0
    while completed < samples:
        amount = min(batch_size, samples - completed)
        channel.send(b"2\n" * amount)
        block = channel.read_prompts(amount)
        values = re.findall(rb"Groundbreaking: ([0-9]+)", block)
        if len(values) != amount:
            raise ValueError(f"expected {amount} observations, received {len(values)}")
        observations.update(int(value) for value in values)
        completed += amount
        if completed == samples or completed % 50_000 == 0:
            print(f"collected {completed}/{samples}", file=sys.stderr)

    return bits, observations


def recover_flag(bits, observations):
    value_frequencies = recover_frequencies(observations, FLAG_LENGTH)
    ordered_values = sorted(value_frequencies)
    if len(ordered_values) > 90:
        raise ValueError("proxy alphabet is too large")

    proxies = [chr(33 + index) for index in range(len(ordered_values))]
    value_to_proxy = dict(zip(ordered_values, proxies))
    proxy_to_value = {proxy: value for value, proxy in value_to_proxy.items()}
    proxy_frequencies = {
        value_to_proxy[value]: frequency
        for value, frequency in value_frequencies.items()
    }

    proxy_root = build_tree(proxy_frequencies)
    proxy_text = decode(bits, proxy_root)
    if len(proxy_text) != FLAG_LENGTH:
        raise ValueError("decoded text has the wrong length")

    matrix = []
    vector = []
    for proxy, actual in zip(proxy_text[: len(KNOWN)], KNOWN):
        value = ord(actual)
        matrix.append([value**power for power in range(5, -1, -1)])
        vector.append(proxy_to_value[proxy])
    coefficients = solve_linear_system(matrix, vector)

    proxy_to_actual = {}
    for codepoint in range(32, 127):
        output = evaluate_polynomial(coefficients, codepoint)
        if output.denominator != 1:
            continue
        proxy = value_to_proxy.get(int(output))
        if proxy is not None:
            proxy_to_actual[proxy] = chr(codepoint)

    missing = set(proxy_text) - set(proxy_to_actual)
    if missing:
        raise ValueError(f"unmapped proxy symbols: {sorted(missing)!r}")

    flag = "".join(proxy_to_actual[proxy] for proxy in proxy_text)
    if not flag.startswith("Securinets{") or not flag.endswith("}"):
        raise ValueError("recovered text does not have the expected wrapper")

    actual_root = build_tree(Counter(flag))
    codes = make_codes(actual_root)
    if "".join(codes[symbol] for symbol in flag) != bits:
        raise ValueError("recovered text does not reproduce the binary string")
    return flag


def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("host", nargs="?")
    parser.add_argument("port", nargs="?", type=int)
    parser.add_argument("--samples", type=int, default=220_000)
    parser.add_argument("--batch", type=int, default=4_000)
    args = parser.parse_args()
    if (args.host is None) != (args.port is None):
        parser.error("provide both host and port, or neither for a local solve")
    if args.samples < 1 or args.batch < 1:
        parser.error("sample and batch counts must be positive")
    return args


def main():
    args = parse_args()
    channel = Channel(args.host, args.port)
    try:
        bits, observations = collect(channel, args.samples, args.batch)
    finally:
        channel.close()
    print(recover_flag(bits, observations))


if __name__ == "__main__":
    main()

import java.lang.reflect.AccessibleObject;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayDeque;
import java.util.Base64;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;


public class Exploit {
    private static String word(int... letters) {
        char[] out = new char[letters.length];
        for (int i = 0; i < letters.length; i++) out[i] = (char) letters[i];
        return new String(out);
    }

    private static byte[] hash(byte[]... chunks) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        for (byte[] chunk : chunks) md.update(chunk);
        return md.digest();
    }

    private static String hex(byte[] data) {
        StringBuilder out = new StringBuilder();
        for (byte value : data) out.append(String.format("%02x", value & 255));
        return out.toString();
    }

    public static String run(Main.LarpReview review, String nonce) throws Exception {
        String openName = word(115,101,116,65,99,99,101,115,115,105,98,108,101);
        Method open = AccessibleObject.class.getMethod(openName, boolean.class);

        String fieldsName = word(103,101,116,68,101,99,108,97,114,101,100,
                                 70,105,101,108,100,115,48);
        Method rawFields = Class.class.getDeclaredMethod(fieldsName, boolean.class);
        open.invoke(rawFields, true);
        Field[] fields = (Field[]) rawFields.invoke(Main.LarpReview.class, false);

        Object[] roots = null;
        for (Field field : fields) {
            if (field.getType() == Object[].class) {
                open.invoke(field, true);
                roots = (Object[]) field.get(review);
            }
        }
        if (roots == null) return "";

        String methodsName = word(103,101,116,68,101,99,108,97,114,101,100,
                                  77,101,116,104,111,100,115,48);
        Method rawMethods = Class.class.getDeclaredMethod(methodsName, boolean.class);
        open.invoke(rawMethods, true);

        ArrayDeque<Object> queue = new ArrayDeque<>();
        Collections.addAll(queue, roots);
        Set<Object> seen = Collections.newSetFromMap(new IdentityHashMap<>());
        byte[][] pieces = new byte[4][];
        Main.Envelope envelope = null;

        while (!queue.isEmpty()) {
            Object item = queue.removeFirst();
            if (item == null || !seen.add(item)) continue;
            if (item instanceof Main.Trail trail) {
                Collections.addAll(queue, trail.walk());
                continue;
            }
            if (item instanceof Main.Envelope found) {
                envelope = found;
                continue;
            }

            Method[] methods = (Method[]) rawMethods.invoke(item.getClass(), false);
            for (Method method : methods) {
                if (method.getParameterCount() != 0 || method.getReturnType() != String.class)
                    continue;
                try {
                    open.invoke(method, true);
                    String value = (String) method.invoke(item);
                    byte[] packed = Base64.getUrlDecoder().decode(value);
                    if (packed.length != 13 || packed[0] < 0 || packed[0] > 3) continue;
                    byte[] body = java.util.Arrays.copyOf(packed, 9);
                    byte[] tag = hash(nonce.getBytes(StandardCharsets.US_ASCII), body,
                                      "MAX".getBytes(StandardCharsets.US_ASCII));
                    boolean valid = true;
                    for (int i = 0; i < 4; i++) valid &= packed[9 + i] == tag[i];
                    if (valid) pieces[packed[0]] = java.util.Arrays.copyOfRange(packed, 1, 9);
                } catch (Exception ignored) {
                }
            }
        }

        if (envelope == null) return "";
        byte[] key = new byte[32];
        for (int i = 0; i < 4; i++) {
            if (pieces[i] == null) return "";
            for (int j = 0; j < 8; j++) key[i * 8 + j] = pieces[i][j];
        }
        byte[] stream = hash(nonce.getBytes(StandardCharsets.US_ASCII), key);
        byte[] ciphertext = envelope.ciphertext();
        byte[] receipt = new byte[ciphertext.length];
        for (int i = 0; i < receipt.length; i++) receipt[i] = (byte) (ciphertext[i] ^ stream[i]);
        return hex(hash(nonce.getBytes(StandardCharsets.US_ASCII), receipt));
    }
}

