#!/usr/bin/env python3
import socket
import sys

from attachments.detector import Detector, PRINTABLE


def solve():
    detector = Detector()
    words = []

    for branch in detector.branches:
        for channel, head in zip(branch["weight"], branch["head"]):
            if head >= 0:
                continue
            word = bytes(
                max(
                    PRINTABLE,
                    key=lambda char: sum(
                        a * b for a, b in zip(detector.embedding[char], weights)
                    ),
                )
                for weights in channel
            )
            if b"*/" not in word and word not in words:
                words.append(word)

    payload = b""
    score = detector.score(payload)

    while score >= detector.threshold:
        best = None
        for word in words:
            for separator in ((b"",) if not payload else (b" ", b"_", b"~", b"|")):
                extra = separator + word
                trial = payload + extra
                if len(trial) > detector.max_note or b"*/" in trial:
                    continue
                new_score = detector.score(trial)
                gain = score - new_score
                if gain <= 0:
                    continue
                key = (gain / len(extra), gain)
                if best is None or key > best[0]:
                    best = (key, word, trial, new_score)
        if best is None:
            raise RuntimeError("no payload found")
        _, word, payload, score = best
        words.remove(word)

    return detector, payload


def send(host, port, payload):
    with socket.create_connection((host, port)) as sock:
        data = b""
        while b"note> " not in data:
            data += sock.recv(4096)
        sock.sendall(payload + b"\n")
        while True:
            block = sock.recv(4096)
            if not block:
                break
            sys.stdout.buffer.write(block)


def main():
    detector, payload = solve()
    print(payload.decode(), flush=True)
    print(
        f"{len(payload)}/{detector.max_note} bytes, logit {detector.score(payload):.4f}",
        flush=True,
    )

    if len(sys.argv) == 3:
        send(sys.argv[1], int(sys.argv[2]), payload)
    elif len(sys.argv) != 1:
        raise SystemExit(f"usage: {sys.argv[0]} [host port]")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3

import os
from pathlib import Path
import re
import socket
import subprocess
import sys


ROOT = Path(__file__).resolve().parent
PAYLOAD = br"\u0074reasure"
FLAG_PATTERN = re.compile(rb"Securinets\{[^}\r\n]+\}")
PROMPT = b"code> "


def extract_flag(output):
    match = FLAG_PATTERN.search(output)
    if match is None:
        raise RuntimeError(f"flag not found in service output: {output!r}")
    return match.group(0).decode()


def solve_local():
    environment = os.environ.copy()
    environment["FLAG_PATH"] = str(ROOT / "flag.txt")
    result = subprocess.run(
        ["node", "chall.js"],
        cwd=ROOT,
        env=environment,
        input=PAYLOAD + b"\n",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=5,
        check=True,
    )
    return extract_flag(result.stdout)


def solve_remote(host, port):
    with socket.create_connection((host, port), timeout=10) as connection:
        output = bytearray()
        while PROMPT not in output:
            chunk = connection.recv(4096)
            if not chunk:
                raise EOFError("service closed before the prompt")
            output.extend(chunk)

        connection.sendall(PAYLOAD + b"\n")
        while FLAG_PATTERN.search(output) is None:
            chunk = connection.recv(4096)
            if not chunk:
                break
            output.extend(chunk)

    return extract_flag(bytes(output))


def main():
    if len(sys.argv) == 1:
        print(solve_local())
        return
    if len(sys.argv) == 3:
        print(solve_remote(sys.argv[1], int(sys.argv[2])))
        return
    raise SystemExit(f"usage: {sys.argv[0]} [host port]")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3

from __future__ import annotations

from pathlib import Path
import re
import struct
import zlib


MAGIC = b"GFNT"


def decoded_streams(pdf: bytes):
    pattern = re.compile(
        rb"<<(.*?)>>\s*stream\r?\n(.*?)\r?\nendstream",
        re.DOTALL,
    )
    for dictionary, stream in pattern.findall(pdf):
        if b"/FlateDecode" in dictionary:
            try:
                yield zlib.decompress(stream)
            except zlib.error:
                continue
        else:
            yield stream


def extract_ghost_codes(pdf: bytes) -> bytes:
    line_pattern = re.compile(
        rb"BT\s+/FG\s+[-0-9.]+\s+Tf\s+[-0-9.]+\s+[-0-9.]+\s+Td\s+"
        rb"<([0-9A-Fa-f]+)>\s+Tj\s+ET"
    )

    codes = bytearray()
    for stream in decoded_streams(pdf):
        for encoded_hex in line_pattern.findall(stream):
            codes.extend(bytes.fromhex(encoded_hex.decode("ascii")))

    if not codes:
        raise ValueError("no text rendered with the /FG font was found")

    for code in codes:
        visible = code & 0x7F
        if not 0x20 <= visible <= 0x7E:
            raise ValueError(f"unexpected ghost character code: 0x{code:02x}")

    return bytes(codes)


def decode_payload(codes: bytes) -> bytes:
    bits = [(code >> 7) & 1 for code in codes]
    packed = bytearray()
    for offset in range(0, len(bits) - 7, 8):
        value = 0
        for bit in bits[offset:offset + 8]:
            value = (value << 1) | bit
        packed.append(value)

    if not packed.startswith(MAGIC):
        raise ValueError("the hidden stream does not start with the GFNT marker")
    if len(packed) < 6:
        raise ValueError("truncated payload header")

    flag_length = struct.unpack(">H", packed[4:6])[0]
    payload_end = 6 + flag_length
    crc_end = payload_end + 4
    if len(packed) < crc_end:
        raise ValueError("truncated hidden payload")

    flag = bytes(packed[6:payload_end])
    stored_crc = struct.unpack(">I", packed[payload_end:crc_end])[0]
    actual_crc = zlib.crc32(flag) & 0xFFFFFFFF
    if stored_crc != actual_crc:
        raise ValueError(
            f"CRC mismatch: stored 0x{stored_crc:08x}, calculated 0x{actual_crc:08x}"
        )

    return flag


def main() -> None:
    path = Path(__file__).with_name("invoice.pdf")
    flag = decode_payload(extract_ghost_codes(path.read_bytes()))
    print(flag.decode("ascii"))


if __name__ == "__main__":
    main()

